// Exponential delays from a committed table (ARCHITECTURE §5.1, §5.6): Poisson arrivals, think times and jitter, with no
// Math.log at run time. packages/sim/core/exp-quantiles.ts is generated by scripts/tables/exp-quantiles.ts, and its entries
// are the means of 1,024 equal-probability bins of the unit exponential, in units of 1/65536, adding up to exactly 1,024 · 65,536.

import { EXP_BINS, EXP_QUANTILES, EXP_SCALE } from './exp-quantiles'
import { divRound } from './int'
import { below } from './rng'
import type { Rng } from './rng'
import type { Us } from './types'

export { EXP_BINS, EXP_QUANTILES, EXP_SCALE }

/**
 * An exponentially distributed delay of mean `meanNum / meanDen` µs, rounded to whole µs (halves up): draw a bin with
 * `below(1024)` and return `round(entry · meanNum / (65536 · meanDen))` in exact integer arithmetic. The mean is a fraction so
 * that a rate that does not divide a second still has an exact mean: arrivals at `r` requests per second ×1,000 are
 * `expDelayUs(rng, 1_000_000_000, r)`. The table's own mean is exactly 1, and the delay is at most 1 + ln 1024 ≈ 7.93 times its mean [derived].
 */
export function expDelayUs(rng: Rng, meanNum: number, meanDen = 1): Us {
  return divRound(EXP_QUANTILES[below(rng, EXP_BINS)] * meanNum, EXP_SCALE * meanDen)
}
